`timescale 1ns / 1ps
// Repro for data_byte_fail: data bits must be sent least significant bit first.
module tb_uart_repro;
    localparam integer CPB = 4;

    reg        clk   = 1'b0;
    reg        rst   = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data  = 8'd0;
    wire       tx;
    wire       busy;

    integer passed = 0;
    integer failed = 0;
    integer i, j, k;
    reg [10:0] frame;
    reg [7:0]  d;
    reg [8*64-1:0] nonce;

    uart_frame_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #5 clk = ~clk;

    task capture_frame(input [7:0] val);
        begin
            @(negedge clk); data = val; start = 1'b1;
            @(negedge clk); start = 1'b0;
            @(negedge clk);
            for (i = 0; i < 11; i = i + 1) begin
                frame[i] = tx;
                repeat (CPB) @(negedge clk);
            end
            while (busy) @(negedge clk);
            repeat (2) @(negedge clk);
        end
    endtask

    initial begin
        nonce = 0;
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = 0;
        repeat (3) @(negedge clk);
        rst = 1'b0;
        repeat (2) @(negedge clk);
        for (k = 0; k < 3; k = k + 1) begin
            case (k)
                0: d = 8'h01;
                1: d = 8'hA1;
                default: d = 8'hF0;
            endcase
            capture_frame(d);
            if (frame[0] === 1'b0) passed = passed + 1;
            else begin failed = failed + 1; $display("FAIL: start bit not low for data %h", d); end
            for (j = 0; j < 8; j = j + 1) begin
                if (frame[1 + j] === d[j]) passed = passed + 1;
                else begin
                    failed = failed + 1;
                    $display("FAIL: data %h bit %0d sent as %b, expected %b (LSB first)", d, j, frame[1 + j], d[j]);
                end
            end
        end
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
=== END FILE ===
