// Repro for frame_period_fail: a frame (start + 8 data + parity + stop) must
// keep busy high for 11 * CLKS_PER_BIT clock cycles.
module tb_uart_repro;
    localparam integer CPB = 4;

    reg        clk   = 1'b0;
    reg        rst   = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data  = 8'd0;
    wire       tx;
    wire       busy;

    integer passed = 0;
    integer failed = 0;
    integer k;
    integer cycles;
    reg [7:0] d;
    reg [8*64-1:0] nonce;

    uart_frame_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #5 clk = ~clk;

    initial begin
        nonce = 0;
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = 0;
        repeat (3) @(negedge clk);
        rst = 1'b0;
        repeat (2) @(negedge clk);
        for (k = 0; k < 2; k = k + 1) begin
            d = (k == 0) ? 8'h55 : 8'hC3;
            @(negedge clk); data = d; start = 1'b1;
            @(negedge clk); start = 1'b0;
            // busy rose on the posedge just before this negedge. Count one
            // cycle per negedge at which busy is still high; the count equals
            // the number of clock cycles busy was high.
            cycles = 0;
            while (busy && cycles < 200) begin
                cycles = cycles + 1;
                @(negedge clk);
            end
            if (cycles == 11 * CPB) passed = passed + 1;
            else begin
                failed = failed + 1;
                $display("FAIL: data %h frame lasted %0d cycles, expected %0d", d, cycles, 11 * CPB);
            end
            if (tx === 1'b1) passed = passed + 1;
            else begin failed = failed + 1; $display("FAIL: tx not idle-high after frame"); end
            repeat (2) @(negedge clk);
        end
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
